import{_ as t,C as i,c as n,o as l,aa as a,G as d}from"./chunks/framework.tkU0Ryf1.js";const b=JSON.parse('{"title":"Code Agent 项目的上下文文件设计指南","description":"以 AGENTS.md、项目背景、架构文档和 OpenSpec 构成渐进式披露的最小上下文体系","frontmatter":{"title":"Code Agent 项目的上下文文件设计指南","description":"以 AGENTS.md、项目背景、架构文档和 OpenSpec 构成渐进式披露的最小上下文体系","date":"2026-08-18T16:30:00.000Z","tags":["AI工具","工程化"]},"headers":[],"relativePath":"posts/Code Agent 项目的上下文文件设计指南.md","filePath":"posts/Code Agent 项目的上下文文件设计指南.md","lastUpdated":1787021004000}'),p={name:"posts/Code Agent 项目的上下文文件设计指南.md"};function o(r,s,h,c,k,g){const e=i("MermaidDiagram");return l(),n("div",null,[s[0]||(s[0]=a(`<h1 id="code-agent-项目的上下文文件设计指南" tabindex="-1">Code Agent 项目的上下文文件设计指南 <a class="header-anchor" href="#code-agent-项目的上下文文件设计指南" aria-label="Permalink to &quot;Code Agent 项目的上下文文件设计指南&quot;">​</a></h1><p>与 Code Agent 协作时，最常见的问题不是“上下文文件太少”，而是同一事实被复制到多份文件：项目介绍写进 README，技术栈又写进 <code>CONTEXT.md</code>，执行规则散落在提示词里，任务进度继续追加到 <code>MEMORY.md</code>。文件越多，Agent 读到冲突和过期内容的概率越高。</p><p>一个健壮的项目不需要维护一套庞大的“AI 文档系统”。更实用的结构只有四层：</p><ol><li><code>AGENTS.md</code>：操作协议与上下文入口；</li><li><code>docs/context.md</code> 或 <code>PROJECT.md</code>：项目背景；</li><li><code>docs/architecture.md</code>：系统设计；</li><li><code>openspec/</code>：当前行为规格与变更执行。</li></ol><p>这四层分别回答“怎样工作”“为什么做”“系统怎样组成”和“这次改变什么”。其他文件只应在真实需求出现时增加。</p><h2 id="_1-设计原则-一条事实只有一个所有者" tabindex="-1">1. 设计原则：一条事实只有一个所有者 <a class="header-anchor" href="#_1-设计原则-一条事实只有一个所有者" aria-label="Permalink to &quot;1. 设计原则：一条事实只有一个所有者&quot;">​</a></h2><p>上下文文件的价值不是让 Agent 一次性读完项目，而是帮助它找到当前任务所需的事实源。因此，设计这些文件时应遵循四个原则：</p><ul><li><strong>单一所有者</strong>：一条事实只在一个地方维护，其他文件只引用它。</li><li><strong>渐进式披露</strong>：先加载操作规则，再根据任务按需加载业务、架构和规格。</li><li><strong>可验证事实优先</strong>：代码、测试、配置和 schema 比自然语言摘要更可信。</li><li><strong>复杂度触发</strong>：没有真实内容时不创建空文件，也不为未来可能需要的场景预先搭建文档体系。</li></ul><p>文件名本身并不能保证公共语义。例如，社区中确实存在大量 <code>CONTEXT.md</code>，但它没有统一的 schema、位置或自动加载规则。团队可以使用这个名字，却必须自行定义它负责什么以及 Agent 何时读取。</p><h2 id="_2-agents-md-操作协议与导航入口" tabindex="-1">2. <code>AGENTS.md</code>：操作协议与导航入口 <a class="header-anchor" href="#_2-agents-md-操作协议与导航入口" aria-label="Permalink to &quot;2. \`AGENTS.md\`：操作协议与导航入口&quot;">​</a></h2><p><a href="https://agents.md/" target="_blank" rel="noreferrer"><code>AGENTS.md</code></a> 是目前最接近跨工具共识的 Agent 指令文件。它应当告诉 Agent 在这个仓库中如何工作，而不是重新介绍整个项目。</p><p>适合写入：</p><ul><li>项目常用的安装、构建、测试和 lint 命令；</li><li>修改完成后必须执行的验证；</li><li>不能直接编辑的生成文件及其源文件位置；</li><li>安全、数据和迁移方面的约束；</li><li>指向项目背景、架构、OpenSpec 和机器合同的索引；</li><li>无法从代码和配置中直接发现的重要约定。</li></ul><p>不适合写入：</p><ul><li>完整产品介绍；</li><li>大段架构说明；</li><li>当前任务进度；</li><li>可以从 <code>package.json</code>、构建脚本或 CI 直接得到的版本清单；</li><li>README 和其他文档的复制内容。</li></ul><p>一个精简的示例：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Repository instructions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Commands</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Install: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm install\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Build: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:build\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Test: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm test\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Required validation</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Documentation changes must pass </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:build\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not edit generated files under </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`docs/public/generated/\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Context routing</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Product or domain changes: read </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`docs/context.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Architectural changes: read </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`docs/architecture.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and relevant ADRs.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Feature work: read the relevant </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`openspec/changes/&lt;change-id&gt;/\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span></code></pre></div><p>大型 monorepo 可以在子目录增加嵌套的 <code>AGENTS.md</code>，但子文件只应描述相对根文件的差异，避免复制父级规则。</p><h3 id="参考定义与实现" tabindex="-1">参考定义与实现 <a class="header-anchor" href="#参考定义与实现" aria-label="Permalink to &quot;参考定义与实现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>可直接读取的资料</th><th>用途</th></tr></thead><tbody><tr><td>开放格式主页</td><td><a href="https://agents.md/" target="_blank" rel="noreferrer">AGENTS.md</a></td><td>定义文件定位、推荐内容、嵌套作用域，并提供最小示例</td></tr><tr><td>格式示例</td><td><a href="https://agents.md/#examples" target="_blank" rel="noreferrer">AGENTS.md 示例入口</a></td><td>查看真实仓库如何组织 setup、test、style 等规则</td></tr><tr><td>标准实现</td><td><a href="https://github.com/openai/codex/blob/main/AGENTS.md" target="_blank" rel="noreferrer">OpenAI Codex 的 AGENTS.md</a></td><td>参考大型 Rust monorepo 的构建、测试和子目录约束</td></tr><tr><td>标准实现</td><td><a href="https://github.com/apache/airflow/blob/main/AGENTS.md" target="_blank" rel="noreferrer">Apache Airflow 的 AGENTS.md</a></td><td>参考大型 Python 项目的开发命令、测试和贡献约束</td></tr></tbody></table><p>需要注意：<code>AGENTS.md</code> 是开放约定，不是带固定字段和版本化语法的正式标准。它规定了可发现的文件名与作用域，但 Markdown 章节仍由项目自行设计。</p><h2 id="_3-docs-context-md-或-project-md-项目背景" tabindex="-1">3. <code>docs/context.md</code> 或 <code>PROJECT.md</code>：项目背景 <a class="header-anchor" href="#_3-docs-context-md-或-project-md-项目背景" aria-label="Permalink to &quot;3. \`docs/context.md\` 或 \`PROJECT.md\`：项目背景&quot;">​</a></h2><p>项目背景负责解释业务世界，而不是代码世界。它的读者需要理解项目为何存在、服务谁、解决什么问题，以及哪些事情明确不属于项目范围。</p><p>推荐内容：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Project context</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Purpose</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Users</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Core scenarios</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Domain terms</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Scope</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Non-goals</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Business rules</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## External constraints</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Sources of truth</span></span></code></pre></div><p><code>docs/context.md</code> 与 <code>PROJECT.md</code> 没有本质差异，应当二选一：</p><ul><li>希望强调产品目的和项目边界时，可以使用 <code>PROJECT.md</code>；</li><li>希望作为业务、领域和组织背景的综合入口时，可以使用 <code>docs/context.md</code>。</li></ul><p>不要同时维护两份内容相近的文件。技术栈、组件关系和部署拓扑属于架构层；单次需求和验收条件属于 OpenSpec；临时任务状态则不应进入长期项目背景。</p><p>对于目标直接、领域知识很少的小工具，这一层可以完全省略。</p><h3 id="参考定义与实现-1" tabindex="-1">参考定义与实现 <a class="header-anchor" href="#参考定义与实现-1" aria-label="Permalink to &quot;参考定义与实现&quot;">​</a></h3><p><code>context.md</code> 和 <code>PROJECT.md</code> <strong>没有官方 schema 或跨工具标准实现</strong>。这里标准化的是信息职责，而不是文件名。可参考以下开放资料选择内容：</p><table tabindex="0"><thead><tr><th>类型</th><th>可直接读取的资料</th><th>可借鉴内容</th></tr></thead><tbody><tr><td>产品背景参考</td><td><a href="https://github.com/cline/prompts/blob/main/.clinerules/memory-bank.md" target="_blank" rel="noreferrer">Cline Memory Bank：projectBrief 与 productContext</a></td><td>项目范围、目标、用户问题和产品行为；这是 Cline 的社区实现，不是通用标准</td></tr><tr><td>架构背景模板</td><td><a href="https://docs.arc42.org/section-1/" target="_blank" rel="noreferrer">arc42：Introduction and Goals</a></td><td>目标、质量目标、利益相关者</td></tr><tr><td>系统边界模板</td><td><a href="https://docs.arc42.org/section-3/" target="_blank" rel="noreferrer">arc42：Context and Scope</a></td><td>业务上下文、外部系统和接口边界</td></tr><tr><td>本文建议模板</td><td>本节的 <code>Project context</code> 示例</td><td>适合作为团队自定义 <code>context.md</code>/<code>PROJECT.md</code> 的最小起点</td></tr></tbody></table><p>因为没有公共标准，必须在 <code>AGENTS.md</code> 中显式写出文件路径、读取触发条件和维护边界，不能假设 Agent 会自动发现它。</p><h2 id="_4-docs-architecture-md-系统设计" tabindex="-1">4. <code>docs/architecture.md</code>：系统设计 <a class="header-anchor" href="#_4-docs-architecture-md-系统设计" aria-label="Permalink to &quot;4. \`docs/architecture.md\`：系统设计&quot;">​</a></h2><p>架构文档负责描述当前系统的稳定结构与约束，重点是代码目录本身无法清楚表达的信息：系统边界、组件职责、关键数据流、运行方式、部署关系和跨模块不变量。</p><p>可以从 <a href="https://arc42.org/overview" target="_blank" rel="noreferrer">arc42</a> 的架构文档维度中选择必要章节，并使用 <a href="https://c4model.com/diagrams" target="_blank" rel="noreferrer">C4 Model</a> 表达不同层级的系统视图：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Architecture</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Goals and quality attributes</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## System context</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Components</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Data flow</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Runtime scenarios</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Deployment</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Cross-cutting constraints</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Invariants</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Risks and technical debt</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Related ADRs</span></span></code></pre></div><p>这不是要求每个项目填写完整模板。一个只有少量文件、边界直观的项目不需要专门的架构文档；当多个服务、模块或部署环境之间的关系仅靠代码难以理解时，再创建它。</p><p>架构文档描述“现在是什么样”，重要决策的历史原因则交给 ADR。这样可以避免 <code>architecture.md</code> 逐渐变成不可维护的会议记录。</p><h3 id="参考定义与实现-2" tabindex="-1">参考定义与实现 <a class="header-anchor" href="#参考定义与实现-2" aria-label="Permalink to &quot;参考定义与实现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>可直接读取的资料</th><th>用途</th></tr></thead><tbody><tr><td>架构模板定义</td><td><a href="https://arc42.org/overview" target="_blank" rel="noreferrer">arc42 Template Overview</a></td><td>了解目标、约束、上下文、构建块、运行时、部署、决策和风险等完整维度</td></tr><tr><td>官方模板</td><td><a href="https://arc42.org/download" target="_blank" rel="noreferrer">arc42 Downloads</a></td><td>下载 Markdown、GitHub Markdown、AsciiDoc 等可直接采用的模板，包含中文版本</td></tr><tr><td>视图标准参考</td><td><a href="https://c4model.com/diagrams" target="_blank" rel="noreferrer">C4 Model Diagrams</a></td><td>选择 System Context、Container、Component 等不同缩放层级</td></tr><tr><td>精简实现</td><td><a href="https://canvas.arc42.org/downloads" target="_blank" rel="noreferrer">arc42 Architecture Communication Canvas</a></td><td>对完整 arc42 过重时，使用 Markdown + Mermaid 的单页架构画布</td></tr></tbody></table><p><code>architecture.md</code> 同样没有唯一公共文件名。arc42 提供内容模板，C4 提供建模视图；本文建议把它们裁剪后落入一个可被 Agent 索引的 Markdown 入口。</p><h2 id="_5-openspec-行为真相与变更执行" tabindex="-1">5. <code>openspec/</code>：行为真相与变更执行 <a class="header-anchor" href="#_5-openspec-行为真相与变更执行" aria-label="Permalink to &quot;5. \`openspec/\`：行为真相与变更执行&quot;">​</a></h2><p>OpenSpec 不只是一个 <code>tasks.md</code> 生成器。它同时管理系统当前行为和单次变化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openspec/</span></span>
<span class="line"><span>├── specs/                    # 系统当前行为</span></span>
<span class="line"><span>└── changes/</span></span>
<span class="line"><span>    └── &lt;change-id&gt;/</span></span>
<span class="line"><span>        ├── proposal.md       # 为什么改、范围是什么</span></span>
<span class="line"><span>        ├── specs/            # 行为变化及验收场景</span></span>
<span class="line"><span>        ├── design.md         # 技术方案与取舍</span></span>
<span class="line"><span>        └── tasks.md          # 执行步骤与验证</span></span></code></pre></div><p>根据 <a href="https://openspec.dev/docs/overview" target="_blank" rel="noreferrer">OpenSpec 核心模型</a>，默认流程是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proposal → specs → design → tasks → implement → archive</span></span>
<span class="line"><span>   why       what      how      steps        merge into truth</span></span></code></pre></div><ul><li><code>openspec/specs/</code> 描述系统当前真实行为；</li><li><code>openspec/changes/</code> 描述准备进行的变化；</li><li>proposal 负责意图和范围；</li><li>delta specs 负责可观察的需求与场景；</li><li>design 负责技术方案；</li><li>tasks 负责任务顺序和完成状态；</li><li>archive 将完成的变化合并回主 specs。</li></ul><p>因此，采用 OpenSpec 后通常不再需要自己维护全局 <code>TASKS.md</code>、<code>PLAN.md</code> 或 <code>STATUS.md</code>。更完整的安装与命令说明可参考站内的<a href="/posts/OpenSpec 使用指南">《OpenSpec 使用指南》</a>。</p><h3 id="参考定义与实现-3" tabindex="-1">参考定义与实现 <a class="header-anchor" href="#参考定义与实现-3" aria-label="Permalink to &quot;参考定义与实现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>可直接读取的资料</th><th>用途</th></tr></thead><tbody><tr><td>核心定义</td><td><a href="https://openspec.dev/docs/overview" target="_blank" rel="noreferrer">OpenSpec Core Concepts</a></td><td>定义 specs、changes、delta specs、artifacts 和 archive</td></tr><tr><td>规格写法</td><td><a href="https://openspec.dev/docs/writing-specs" target="_blank" rel="noreferrer">Writing Good Specs</a></td><td>直接读取 requirement、GIVEN/WHEN/THEN scenario 的编写规范</td></tr><tr><td>评审标准</td><td><a href="https://openspec.dev/docs/reviewing-changes" target="_blank" rel="noreferrer">Reviewing a Change</a></td><td>按 proposal → specs → design → tasks 顺序审查变更</td></tr><tr><td>标准实现</td><td><a href="https://openspec.dev/docs/examples" target="_blank" rel="noreferrer">Examples &amp; Recipes</a></td><td>查看完整 change 目录、纯重构和逐步生成等实例</td></tr><tr><td>机器接口</td><td><a href="https://openspec.dev/docs/reference/cli" target="_blank" rel="noreferrer">OpenSpec CLI Reference</a></td><td>Agent 可用 <code>status</code>、<code>instructions</code>、<code>templates</code>、<code>validate</code> 获取结构化状态和校验结果</td></tr><tr><td>本文的实际工作包</td><td><a href="https://github.com/helloahao096/helloahao096.github.io/tree/main/openspec/changes/document-agent-context-model" target="_blank" rel="noreferrer"><code>document-agent-context-model</code></a></td><td>本文从 proposal、spec、design、tasks 到验证的标准实现；合并到主分支后可直接读取</td></tr></tbody></table><p>OpenSpec 是这四层中结构最明确的一层：默认 schema 定义 artifact 依赖，CLI 可以验证 change；但它仍允许项目自定义 schema，因此 Agent 应优先读取项目自己的 <code>openspec/config.yaml</code> 和 CLI 输出。</p><h2 id="_6-四层如何渐进式加载" tabindex="-1">6. 四层如何渐进式加载 <a class="header-anchor" href="#_6-四层如何渐进式加载" aria-label="Permalink to &quot;6. 四层如何渐进式加载&quot;">​</a></h2><p>Agent 不应该在每次任务开始时读取全部文档。合理的读取路径是：</p>`,54)),d(e,{source:""}),s[1]||(s[1]=a(`<p>这就是渐进式披露：<code>AGENTS.md</code> 是路由器，不是百科全书；其他文件只在任务触发对应问题时加载。</p><h2 id="_7-按需扩展-而不是第五个必选层" tabindex="-1">7. 按需扩展，而不是第五个必选层 <a class="header-anchor" href="#_7-按需扩展-而不是第五个必选层" aria-label="Permalink to &quot;7. 按需扩展，而不是第五个必选层&quot;">​</a></h2><h3 id="_7-1-adr-记录重大且持久的决策" tabindex="-1">7.1 ADR：记录重大且持久的决策 <a class="header-anchor" href="#_7-1-adr-记录重大且持久的决策" aria-label="Permalink to &quot;7.1 ADR：记录重大且持久的决策&quot;">​</a></h3><p><a href="https://adr.github.io/" target="_blank" rel="noreferrer">Architecture Decision Record</a> 适合记录存在多个合理选项、会长期影响系统，而且后来者很可能追问“为什么”的决策。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/adr/</span></span>
<span class="line"><span>├── 0001-use-postgresql.md</span></span>
<span class="line"><span>└── 0002-adopt-event-driven-integration.md</span></span></code></pre></div><p>普通实现选择留在 OpenSpec <code>design.md</code> 或代码中即可。只有需要跨越当前变更长期保留的决策，才值得晋升为 ADR。</p><p>可直接采用的资料：</p><ul><li><a href="https://adr.github.io/" target="_blank" rel="noreferrer">ADR 社区定义</a>：解释 ADR、decision log 和常见工具；</li><li><a href="https://adr.github.io/adr-templates/" target="_blank" rel="noreferrer">ADR Templates</a>：比较 Nygard、MADR 等模板；</li><li><a href="https://adr.github.io/madr/" target="_blank" rel="noreferrer">MADR 4.0</a>：维护活跃、结构明确的 Markdown 模板；</li><li><a href="https://github.com/adr/madr/blob/4.0.0/template/adr-template-minimal.md" target="_blank" rel="noreferrer">MADR minimal template</a>：可以直接复制的最小实现。</li></ul><p>ADR 是广泛工程惯例，不存在唯一强制 schema。若项目选择 MADR，应在 <code>AGENTS.md</code> 或 <code>architecture.md</code> 中记录所采用的模板版本和目录。</p><h3 id="_7-2-机器合同-接口和数据边界" tabindex="-1">7.2 机器合同：接口和数据边界 <a class="header-anchor" href="#_7-2-机器合同-接口和数据边界" aria-label="Permalink to &quot;7.2 机器合同：接口和数据边界&quot;">​</a></h3><p>当系统存在稳定接口时，自然语言说明不应成为最终合同：</p><ul><li>HTTP API 使用 OpenAPI；</li><li>事件接口使用 AsyncAPI；</li><li>JSON 数据使用 JSON Schema；</li><li>RPC 或二进制消息使用 Protocol Buffers。</li></ul><p>这些文件可由工具验证、生成客户端或参与契约测试，是比 Markdown 摘要更强的事实源。它们属于具体系统边界，不属于所有项目都要创建的通用 Agent 上下文层。</p><table tabindex="0"><thead><tr><th>合同类型</th><th>官方规范</th><th>标准实现入口</th></tr></thead><tbody><tr><td>HTTP API</td><td><a href="https://spec.openapis.org/oas/latest.html" target="_blank" rel="noreferrer">OpenAPI Specification</a></td><td><code>openapi.yaml</code>/<code>openapi.json</code>；文件名是惯例，规范不强制路径</td></tr><tr><td>事件/消息 API</td><td><a href="https://www.asyncapi.com/docs/reference/specification/latest" target="_blank" rel="noreferrer">AsyncAPI Specification</a></td><td><code>asyncapi.yaml</code>/<code>asyncapi.json</code></td></tr><tr><td>JSON 数据</td><td><a href="https://json-schema.org/draft/2020-12" target="_blank" rel="noreferrer">JSON Schema 2020-12</a></td><td><code>*.schema.json</code>，并在文档中声明 <code>$schema</code></td></tr><tr><td>RPC/消息</td><td><a href="https://protobuf.dev/programming-guides/proto3/" target="_blank" rel="noreferrer">Protocol Buffers Language Guide</a></td><td><code>*.proto</code></td></tr></tbody></table><p>Agent 应直接读取这些合同文件，而不是依赖 <code>architecture.md</code> 对字段、消息或响应结构的二次转述。</p><h3 id="_7-3-design-md-只用于视觉设计系统" tabindex="-1">7.3 <code>DESIGN.md</code>：只用于视觉设计系统 <a class="header-anchor" href="#_7-3-design-md-只用于视觉设计系统" aria-label="Permalink to &quot;7.3 \`DESIGN.md\`：只用于视觉设计系统&quot;">​</a></h3><p><code>DESIGN.md</code> 可以承载颜色、字体、组件、间距和设计 token，适合具有明确视觉系统的产品。但它不等同于软件架构文档，也不是所有代码项目的必选文件。没有独立设计系统时，相关约束放在现有 UI 规范或组件代码中即可。</p><p>Google Labs 已发布一个开放的 <a href="https://github.com/google-labs-code/design.md" target="_blank" rel="noreferrer"><code>DESIGN.md</code> draft specification</a>，其标准实现由 YAML frontmatter 的设计 token 与 Markdown 设计语义组成。可直接读取：</p><ul><li><a href="https://github.com/google-labs-code/design.md/blob/main/docs/spec.md" target="_blank" rel="noreferrer">完整格式规范</a>；</li><li><a href="https://github.com/google-labs-code/design.md#the-format" target="_blank" rel="noreferrer">官方示例</a>；</li><li><a href="https://github.com/google-labs-code/design.md/blob/main/PHILOSOPHY.md" target="_blank" rel="noreferrer">设计理念</a>；</li><li>CLI 校验：<code>npx @google/design.md lint DESIGN.md</code>；</li><li>向 Agent 输出规范：<code>npx @google/design.md spec</code>。</li></ul><p>该格式目前仍标记为 <code>alpha</code>。因此可以在视觉密集型项目中试用并固定版本，但不应把它描述成已经成熟的跨行业标准。</p><h2 id="_8-不建议长期沉淀的文件" tabindex="-1">8. 不建议长期沉淀的文件 <a class="header-anchor" href="#_8-不建议长期沉淀的文件" aria-label="Permalink to &quot;8. 不建议长期沉淀的文件&quot;">​</a></h2><p>以下名称在不同工具和团队中都能见到，但不应默认成为仓库长期事实：</p><ul><li><code>MEMORY.md</code></li><li><code>STATUS.md</code></li><li><code>PROGRESS.md</code></li><li><code>HANDOFF.md</code></li><li><code>LEARNINGS.md</code></li></ul><p>它们通常与 Git、issue、PR、OpenSpec tasks 或代码事实重复，而且更新频率远高于项目背景和架构，最容易失效。需要跨会话交接时，可以使用当前对话、issue/PR 或任务系统；真正持久的发现应晋升到测试、<code>AGENTS.md</code>、架构文档或 ADR，而不是永久累积在记忆文件中。</p><h2 id="_9-推荐目录与采用路径" tabindex="-1">9. 推荐目录与采用路径 <a class="header-anchor" href="#_9-推荐目录与采用路径" aria-label="Permalink to &quot;9. 推荐目录与采用路径&quot;">​</a></h2><p>完整但仍然克制的目录如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AGENTS.md</span></span>
<span class="line"><span>README.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docs/</span></span>
<span class="line"><span>├── context.md                # 有稳定业务/领域背景时</span></span>
<span class="line"><span>├── architecture.md           # 系统边界不再显而易见时</span></span>
<span class="line"><span>└── adr/                      # 有重大持久决策时</span></span>
<span class="line"><span></span></span>
<span class="line"><span>openspec/</span></span>
<span class="line"><span>├── specs/</span></span>
<span class="line"><span>└── changes/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>api/</span></span>
<span class="line"><span>└── openapi.yaml              # 存在 HTTP API 时</span></span>
<span class="line"><span></span></span>
<span class="line"><span>schemas/</span></span>
<span class="line"><span>└── *.schema.json             # 存在共享 JSON 合同时</span></span></code></pre></div><p>按复杂度逐步采用：</p><table tabindex="0"><thead><tr><th>项目情况</th><th>建议配置</th></tr></thead><tbody><tr><td>小型、边界直观</td><td><code>AGENTS.md + openspec/</code></td></tr><tr><td>存在专门业务或领域语义</td><td>增加 <code>docs/context.md</code> 或 <code>PROJECT.md</code></td></tr><tr><td>多模块、多服务或复杂部署</td><td>增加 <code>docs/architecture.md</code></td></tr><tr><td>出现需要长期解释的决策</td><td>增加相关 ADR</td></tr><tr><td>存在稳定 API 或数据交换</td><td>增加相应机器合同</td></tr></tbody></table><h2 id="_10-维护检查表" tabindex="-1">10. 维护检查表 <a class="header-anchor" href="#_10-维护检查表" aria-label="Permalink to &quot;10. 维护检查表&quot;">​</a></h2><p>每次增加或修改上下文时，可以检查：</p><ul><li>这条信息是否已经能从代码、测试、配置或 schema 得到？</li><li>它是否已经在另一份文档中拥有明确的事实来源？</li><li>它属于操作、项目背景、架构，还是单次变化？</li><li>Agent 是否真的需要在执行相关任务时读取它？</li><li>文件是否写明了更新触发条件，而不是只记录创建时的快照？</li><li>删除这段内容后，Agent 是否仍能通过索引找到权威事实？</li></ul><p>如果最后一个问题的答案是“能”，通常应该删除重复内容。</p><h2 id="_11-agent-可直接读取的资料索引" tabindex="-1">11. Agent 可直接读取的资料索引 <a class="header-anchor" href="#_11-agent-可直接读取的资料索引" aria-label="Permalink to &quot;11. Agent 可直接读取的资料索引&quot;">​</a></h2><p>如果希望后续 Agent 不经过搜索就能定位规范，可以在根 <code>AGENTS.md</code> 中维护一份短索引：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Context and standards</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Project/domain context: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`docs/context.md\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Current architecture: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`docs/architecture.md\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Architecture decisions: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`docs/adr/\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (MADR 4.0)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Current behavior specs: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`openspec/specs/\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Active change: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`openspec/changes/&lt;change-id&gt;/\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OpenSpec rules: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`openspec/config.yaml\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTP contract: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`api/openapi.yaml\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Visual design system: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`DESIGN.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (Google Labs alpha spec)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">External definitions:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AGENTS.md: https://agents.md/</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OpenSpec: https://openspec.dev/docs/overview</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> arc42: https://arc42.org/overview</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C4: https://c4model.com/diagrams</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MADR: https://adr.github.io/madr/</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OpenAPI: https://spec.openapis.org/oas/latest.html</span></span></code></pre></div><p>索引只负责指路，不复制这些规范的正文。这样，人和 Agent 都能先读取仓库内的实际文件，需要解释格式时再访问对应的一手资料。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>与 Code Agent 协作的项目不需要维护十几种上下文文件。一个足够健壮的基线是：</p><ul><li>用 <code>AGENTS.md</code> 定义操作协议并提供索引；</li><li>用 <code>docs/context.md</code> 或 <code>PROJECT.md</code> 保存稳定的产品和领域背景；</li><li>用 <code>docs/architecture.md</code> 描述非显而易见的系统结构；</li><li>用 OpenSpec 管理当前行为、单次变化、技术方案和任务执行。</li></ul><p>ADR、机器合同和视觉 <code>DESIGN.md</code> 由真实复杂度触发。其余状态和记忆文件不默认沉淀。上下文体系越小、事实所有权越清楚，Agent 才越容易在正确的时间读取正确的信息。</p>`,41))])}const E=t(p,[["render",o]]);export{b as __pageData,E as default};
